using Godot;
using System;
using System.Collections.Generic;
namespace MySim {
// Read-only head/lens inspection. UV/material evidence does not automatically classify a lens.
// Debug copies and labels are for encrypted captures only, never production lamp placement.
public static class FixtureLensExitDiagnostic {
 sealed class Face {public MeshInstance3D Source;public int Surface,Triangle;public Vector3 A,B,C,ImportedNormal;public Vector2 Ua,Ub,Uc;public Vector3 Centre=>(A+B+C)/3f;public Vector3 Normal=>-(B-A).Cross(C-A).Normalized();public float Area=>(B-A).Cross(C-A).Length()*.5f;}
 static float PointDistance(Vector3 p,Vector3 a,Vector3 b,Vector3 c){var n=(b-a).Cross(c-a);if(n.LengthSquared()>1e-16f){var projected=p-n*(p-a).Dot(n)/n.LengthSquared();var ab=b-a;var ac=c-a;var ap=projected-a;float d00=ab.Dot(ab),d01=ab.Dot(ac),d11=ac.Dot(ac),d20=ap.Dot(ab),d21=ap.Dot(ac),den=d00*d11-d01*d01;if(Mathf.Abs(den)>1e-16f){float v=(d11*d20-d01*d21)/den,w=(d00*d21-d01*d20)/den;if(v>=0&&w>=0&&v+w<=1)return p.DistanceTo(projected);}}float Edge(Vector3 x,Vector3 y){var d=y-x;float t=d.LengthSquared()>1e-16f?Mathf.Clamp((p-x).Dot(d)/d.LengthSquared(),0,1):0;return p.DistanceTo(x+d*t);}return Mathf.Min(Edge(a,b),Mathf.Min(Edge(b,c),Edge(c,a)));}
 static List<object> CollisionEvidence(Face face,Vector3 exit){var result=new List<object>();foreach(var child in face.Source.GetChildren()){if(child is not StaticBody3D body)continue;foreach(var node in body.GetChildren()){if(node is not CollisionShape3D collider||collider.Shape is not ConcavePolygonShape3D shape)continue;var vertices=shape.Data;float nearest=float.PositiveInfinity,match=float.PositiveInfinity;int nearestTriangle=-1,matchingTriangle=-1;for(int i=0;i+2<vertices.Length;i+=3){var a=collider.GlobalTransform*vertices[i];var b=collider.GlobalTransform*vertices[i+1];var c=collider.GlobalTransform*vertices[i+2];float distance=PointDistance(exit,a,b,c);if(distance<nearest){nearest=distance;nearestTriangle=i/3;}float VertexDistance(Vector3 p)=>Mathf.Min(p.DistanceTo(a),Mathf.Min(p.DistanceTo(b),p.DistanceTo(c)));float error=Mathf.Max(VertexDistance(face.A),Mathf.Max(VertexDistance(face.B),VertexDistance(face.C)));if(error<match){match=error;matchingTriangle=i/3;}}result.Add(new{path=collider.GetPath().ToString(),triangles=vertices.Length/3,margin=shape.Margin,querySphereRadius=.08f,queryMargin=0f,nearestTriangle,distanceToExit=nearest,sphereGeometricClearance=nearest-.08f,sphereMarginHeuristicClearance=nearest-.08f-shape.Margin,matchingTriangle,sourceTriangleVertexMaxError=match,origin=V(collider.GlobalPosition),basisX=V(collider.GlobalBasis.X),basisY=V(collider.GlobalBasis.Y),basisZ=V(collider.GlobalBasis.Z),scope="Actual Concave.Data transformed through actual collision node. Margin subtraction is diagnostic heuristic, not solver clearance proof"});}}return result;}
 static float[] V(Vector3 p)=>new[]{p.X,p.Y,p.Z};static float[] U(Vector2 p)=>new[]{p.X,p.Y};
 static float? Intersection(Vector3 origin,Vector3 direction,Face f){var e1=f.B-f.A;var e2=f.C-f.A;var h=direction.Cross(e2);float det=e1.Dot(h);if(Mathf.Abs(det)<1e-8f)return null;float inv=1f/det;var s=origin-f.A;float u=inv*s.Dot(h);if(u<0||u>1)return null;var q=s.Cross(e1);float v=inv*direction.Dot(q);if(v<0||u+v>1)return null;float t=inv*e2.Dot(q);return t>.001f&&t<=2f?t:null;}
 // Call from a physics frame after source wall bodies/material binding exist. Returned roots are
 // separate close-up views, positioned at local origin; caller frames/records them one at a time.
 public static List<Node3D> Write(List<Node3D> layers,int track,string destination,Node3D debugParent=null){
  if(track!=25&&track!=28)throw new ArgumentOutOfRangeException(nameof(track));
  var specs=track==25?new[]{("prop_singapore_floodlights_001",new Vector3(-128.7134f,36.9505f,-258.6009f))}:new[]{("prop_yasmarina_floodlight_pole_short002",new Vector3(102.49315f,34.7173f,515.01625f)),("prop_yasmarina_floodlight_pole_double",new Vector3(-11.45315f,39.9966f,676.53205f))};
  var reports=new List<object>();var views=new List<Node3D>();
  foreach(var spec in specs){var all=new List<Face>();
   foreach(var layer in layers){var nodes=layer.FindChildren("*","MeshInstance3D",true,false);foreach(var node in nodes){var mesh=(MeshInstance3D)node;string name=mesh.Name.ToString();if(mesh.Mesh==null||!mesh.IsVisibleInTree()||!(name==spec.Item1||name.StartsWith(spec.Item1+"_mm",StringComparison.Ordinal)))continue;
    for(int surface=0;surface<mesh.Mesh.GetSurfaceCount();surface++){if(mesh.Mesh is not ArrayMesh array||array.SurfaceGetPrimitiveType(surface)!=Mesh.PrimitiveType.Triangles)continue;using var arrays=mesh.Mesh.SurfaceGetArrays(surface);var vertices=(Vector3[])arrays[(int)Mesh.ArrayType.Vertex];var indices=(int[])arrays[(int)Mesh.ArrayType.Index];var uv=(Vector2[])arrays[(int)Mesh.ArrayType.TexUV];var importedNormals=(Vector3[])arrays[(int)Mesh.ArrayType.Normal];int count=indices?.Length>0?indices.Length:vertices.Length;
     for(int at=0;at+2<count;at+=3){int a=indices?.Length>0?indices[at]:at,b=indices?.Length>0?indices[at+1]:at+1,c=indices?.Length>0?indices[at+2]:at+2;var normal=importedNormals?.Length>Math.Max(a,Math.Max(b,c))?(mesh.GlobalBasis.Inverse().Transposed()*(importedNormals[a]+importedNormals[b]+importedNormals[c])).Normalized():Vector3.Zero;all.Add(new Face{Source=mesh,Surface=surface,Triangle=at/3,A=mesh.GlobalTransform*vertices[a],B=mesh.GlobalTransform*vertices[b],C=mesh.GlobalTransform*vertices[c],ImportedNormal=normal,Ua=uv?.Length>a?uv[a]:Vector2.Zero,Ub=uv?.Length>b?uv[b]:Vector2.Zero,Uc=uv?.Length>c?uv[c]:Vector2.Zero});}
    }
   }nodes.Clear();}
   var heads=new List<Face>();foreach(var f in all){var d=f.Centre-spec.Item2;if(f.Area>1e-8f&&f.Centre.Y>=spec.Item2.Y-6f&&f.Centre.Y<=spec.Item2.Y+1f&&new Vector2(d.X,d.Z).Length()<4f)heads.Add(f);}
   heads.Sort((a,b)=>{int cmp=b.Area.CompareTo(a.Area);if(cmp!=0)return cmp;cmp=StringComparer.Ordinal.Compare(a.Source.Name.ToString(),b.Source.Name.ToString());return cmp!=0?cmp:a.Triangle.CompareTo(b.Triangle);});
   var rows=new List<object>();int label=0;var labels=new Dictionary<Face,string>();foreach(var face in heads){if(face.Normal.Y>-.25f)continue;var hits=new List<(float t,Face f)>();foreach(var other in all){if(ReferenceEquals(face,other))continue;var t=Intersection(face.Centre,face.Normal,other);if(t.HasValue)hits.Add((t.Value,other));}hits.Sort((a,b)=>a.t.CompareTo(b.t));var intersections=new List<object>();foreach(var hit in hits)intersections.Add(new{distance=hit.t,node=hit.f.Source.GetPath().ToString(),surface=hit.f.Surface,triangle=hit.f.Triangle,normal=V(hit.f.Normal),normalAlignment=face.Normal.Dot(hit.f.Normal)});
    var exit=face.Centre+face.Normal*(hits.Count>0?hits[hits.Count-1].t+.09f:.09f);var space=face.Source.GetWorld3D().DirectSpaceState;using var sphere=new PhysicsShapeQueryParameters3D{Shape=new SphereShape3D{Radius=.08f},Transform=new Transform3D(Basis.Identity,exit),CollisionMask=2};var overlaps=space.IntersectShape(sphere,8);var overlapPaths=new List<string>();foreach(var overlap in overlaps)overlapPaths.Add((overlap["collider"].AsGodotObject() as Node)?.GetPath().ToString());var route=new MySimulator.Rebuild.Circuit(track);float progress=route.Find(new MySimulator.Rebuild.Vec(exit.X,exit.Z),out float lateral);var target=route.Point(progress);var ground=Contact.Ground(space,new Vector3(target.x,exit.Y,target.z),exit.Y,100);object occlusion=null;if(ground.found){using var query=PhysicsRayQueryParameters3D.Create(exit,new Vector3(target.x,ground.rawY+.1f,target.z));query.CollisionMask=2;query.HitBackFaces=true;var obstruction=space.IntersectRay(query);if(obstruction.Count>0)occlusion=new{path=(obstruction["collider"].AsGodotObject() as Node)?.GetPath().ToString(),position=V(obstruction["position"].AsVector3())};}
    var material=face.Source.GetActiveMaterial(face.Surface) as StandardMaterial3D;var centroid=(face.Ua+face.Ub+face.Uc)/3f;var scale=material?.Uv1Scale??Vector3.One;var offset=material?.Uv1Offset??Vector3.Zero;var effective=new Vector2(centroid.X*scale.X+offset.X,centroid.Y*scale.Y+offset.Y);var repeated=new Vector2(effective.X-Mathf.Floor(effective.X),effective.Y-Mathf.Floor(effective.Y));string id=face.Source.Name+"/s"+face.Surface+"/t"+face.Triangle;
    if(label<4){labels[face]="F"+label+" "+id;label++;}
    rows.Add(new{id,node=face.Source.GetPath().ToString(),surface=face.Surface,triangle=face.Triangle,area=face.Area,centroid=V(face.Centre),normal=V(face.Normal),importedNormal=V(face.ImportedNormal),computedImportedAgreement=face.Normal.Dot(face.ImportedNormal),collisionEvidence=CollisionEvidence(face,exit),uv=new[]{U(face.Ua),U(face.Ub),U(face.Uc)},effectiveCentroidUV=U(effective),repeatCentroidUV=U(repeated),texture=material?.AlbedoTexture?.ResourcePath,material=material?.ResourceName,transparency=material?.Transparency.ToString(),normalExitIntersections=intersections,exitCandidate=V(exit),exitSphereObstructions=overlapPaths,targetGround=ground.found,targetProgress=progress,targetLateral=lateral,fullWorldOcclusion=occlusion,validated=false,lensRole="unresolved-requires-atlas-and-labelled-closeup"});
   }
   reports.Add(new{target=spec.Item1,measuredShaftTop=V(spec.Item2),headTriangles=heads.Count,downwardFaceDiagnostics=rows,scope="Exact own-fixture intersections to2m; not an emitter approval or external-world occlusion waiver"});
   if(debugParent==null)continue;var root=new Node3D{Name="LensDiagnostic_"+views.Count};debugParent.AddChild(root);
   // Reconstruct selected original triangles with unchanged UV/materials, in a close-up local frame.
   foreach(var face in heads){using var arrays=face.Source.Mesh.SurfaceGetArrays(face.Surface);var indices=(int[])arrays[(int)Mesh.ArrayType.Index];var normals=(Vector3[])arrays[(int)Mesh.ArrayType.Normal];var uv2=(Vector2[])arrays[(int)Mesh.ArrayType.TexUV2];var colours=(Color[])arrays[(int)Mesh.ArrayType.Color];using var tool=new SurfaceTool();tool.Begin(Mesh.PrimitiveType.Triangles);tool.SetMaterial(face.Source.GetActiveMaterial(face.Surface));var points=new[]{face.A,face.B,face.C};var tex=new[]{face.Ua,face.Ub,face.Uc};for(int corner=0;corner<3;corner++){int at=face.Triangle*3+corner,index=indices?.Length>0?indices[at]:at;if(normals?.Length>index)tool.SetNormal((face.Source.GlobalBasis.Inverse().Transposed()*normals[index]).Normalized());tool.SetUV(tex[corner]);if(uv2?.Length>index)tool.SetUV2(uv2[index]);if(colours?.Length>index)tool.SetColor(colours[index]);tool.AddVertex(points[corner]-spec.Item2);}root.AddChild(new MeshInstance3D{Mesh=tool.Commit()});}
   foreach(var pair in labels){var face=pair.Key;var normal=face.Normal;var start=face.Centre-spec.Item2;var arrow=new MeshInstance3D{Position=start+normal*.3f,Mesh=new CylinderMesh{TopRadius=.018f,BottomRadius=.018f,Height=.6f},MaterialOverride=new StandardMaterial3D{AlbedoColor=Colors.Magenta,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded},CastShadow=GeometryInstance3D.ShadowCastingSetting.Off};root.AddChild(arrow);arrow.Quaternion=new Quaternion(Vector3.Up,normal);root.AddChild(new Label3D{Text=pair.Value,Position=start+normal*.7f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,FontSize=32,PixelSize=.004f,NoDepthTest=true});}
   root.SetMeta("target",spec.Item1);root.SetMeta("validated",false);views.Add(root);
  }
  var folder=System.IO.Path.GetDirectoryName(destination);if(!string.IsNullOrEmpty(folder))System.IO.Directory.CreateDirectory(folder);System.IO.File.WriteAllText(destination,System.Text.Json.JsonSerializer.Serialize(new{track,targets=reports,scope="Numeric UV/triangle/exit evidence only; original geometry/UV/collision unchanged. No production light placement enabled"}));return views;
 }
}
}
